<script setup lang="ts">import {ref,watch} from 'vue';const props=defineProps<{open:boolean;title:string;message?:string;confirmText?:string;requirePhrase?:string;danger?:boolean}>();const emit=defineEmits<{confirm:[];cancel:[]}>();const entry=ref('');watch(()=>props.open,()=>entry.value='');</script><template><Teleport to="body"><div v-if="open" class="vx-dialog-backdrop" @click.self="emit('cancel')"><section class="vx-confirm-dialog" role="alertdialog" aria-modal="true" :aria-label="title" @keydown.esc="emit('cancel')"><h2>{{title}}</h2><p>{{message}}</p><label v-if="requirePhrase">Type <strong>{{requirePhrase}}</strong> to confirm<input v-model="entry" autocomplete="off"/></label><footer><button type="button" @click="emit('cancel')">Cancel</button><button type="button" :disabled="Boolean(requirePhrase)&&entry!==requirePhrase" :class="{'vx-danger':danger}" @click="emit('confirm')">{{confirmText||'Confirm'}}</button></footer></section></div></Teleport></template>